package io.knowledgebrain.knowledge;
import java.util.*;
import java.time.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;
import org.postgresql.ds.PGSimpleDataSource;
import static org.assertj.core.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_KNOWLEDGE_DATABASE_URL",matches=".+")
class PublicDiscoveryApiIntegrationTest {
 PublicDiscoveryController api;PublicRecordStore records;ConceptStore concepts;UUID space,actor;UuidV7 ids=new UuidV7(Clock.systemUTC());
 @BeforeEach void setup(){var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_KNOWLEDGE_DATABASE_URL"));ds.setUser("brain_knowledge");ds.setPassword(System.getenv("BRAIN_TEST_KNOWLEDGE_DATABASE_PASSWORD"));org.flywaydb.core.Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();records=new PublicRecordStore(ds,Clock.systemUTC());concepts=new ConceptStore(ds,Clock.systemUTC());api=new PublicDiscoveryController(ds,records,"s".repeat(43),"c".repeat(43));space=ids.next();actor=ids.next();}
 MockHttpServletRequest request(String key){var r=new MockHttpServletRequest();r.setSecure(true);r.addHeader("Authorization","Bearer "+key.repeat(43));return r;}
 UUID publicConcept(String title){return concepts.createWithId(space,ids.next(),actor,title,"", "a".repeat(32),"PUBLIC").conceptId();}
 @Test void scanHasNoPrivateOrProposalRowsAndUsesPinnedNormalizedBytes()throws Exception{UUID earlier=publicConcept("Earlier"),privateId=concepts.create(space,actor,"Private","Secret","a".repeat(32)).conceptId(),publicId=publicConcept("Visible");var r=request("s");r.setParameter("kind","CONCEPT");r.setParameter("after",earlier.toString());r.setParameter("through",publicId.toString());var page=api.snapshots(r).getBody();assertThat(page.items()).extracting(PublicDiscoveryController.Item::entityId).containsExactly(publicId).doesNotContain(privateId);var wire=io.knowledgebrain.contracts.knowledge.publicknowledge.v1.EventEnvelopeV1.parseFrom(Base64.getDecoder().decode(page.items().getFirst().payload()));assertThat(wire.getSpaceId()).isEqualTo(space.toString());var payload=io.knowledgebrain.contracts.knowledge.publicknowledge.v1.PublicKnowledgeChangedPayloadV1.parseFrom(wire.getPayload());assertThat(payload.getVisibility()).isEqualTo("PUBLIC");assertThat(payload.getKind()).isEqualTo("CONCEPT");}
 @Test void canonicalCheckOmitsPrivateForeignAndUnmergedIds()throws Exception{UUID publicId=publicConcept("Visible"),privateId=concepts.create(space,actor,"Private","Secret","a".repeat(32)).conceptId();var json=tools.jackson.databind.json.JsonMapper.builder().build();var p=records.submit(space,actor,"SOURCE","CREATE",null,0,"Pending",json.createObjectNode().put("title","Pending").put("url","").put("citation","Original pending metadata").put("licenseNote","Original metadata"),"Explicit proposal","a".repeat(32));var r=request("c");r.setContentType("application/json");r.setContent(json.writeValueAsBytes(Map.of("spaceId",space,"ids",List.of(publicId,privateId,p.recordId()))));assertThat(api.check(r).getBody()).extracting(PublicDiscoveryController.Check::entityId).containsExactly(publicId);var foreign=request("c");foreign.setContentType("application/json");foreign.setContent(json.writeValueAsBytes(Map.of("spaceId",ids.next(),"ids",List.of(publicId))));assertThat(api.check(foreign).getBody()).isEmpty();}
 @Test void readAndScanCredentialsCannotBeExchangedAndBrowserCookiesFailClosed(){var read=request("c");read.setParameter("kind","CONCEPT");assertThatThrownBy(()->api.snapshots(read)).isInstanceOf(ResponseStatusException.class);var scan=request("s");scan.setContentType("application/json");scan.setContent("{}".getBytes());assertThatThrownBy(()->api.check(scan)).isInstanceOf(ResponseStatusException.class);var cookie=request("s");cookie.addHeader("Cookie","__Host-brain_guest=anything");assertThatThrownBy(()->api.snapshots(cookie)).isInstanceOf(ResponseStatusException.class);var plain=request("s");plain.setSecure(false);assertThatThrownBy(()->api.snapshots(plain)).isInstanceOf(ResponseStatusException.class);}
}
